import re
from dataclasses import dataclass, field
from typing import Optional

HEADING = re.compile(
    r"^## \[(?P<version>[^\]]+)\](?: - (?P<date>\d{4}-\d{2}-\d{2}))?\s*$"
)
COMMENT = re.compile(r"<!--.*?-->", re.DOTALL)


@dataclass
class Release:
    version: str
    date: Optional[str]
    body: list = field(default_factory=list)


def strip_comments(text):
    """Remove HTML comments, and whitespace they leave at the end of a line."""
    marker = "\x00"
    lines = []
    for line in COMMENT.sub(marker, text).split("\n"):
        if marker in line:
            line = line.replace(marker, "")
            if line.strip() == "":
                line = ""
            else:
                line = line.rstrip() if not line.endswith((" ", "\t")) else line.rstrip()
        lines.append(line)
    return "\n".join(lines)


def parse_changelog(text):
    releases = []
    current = None
    for line in strip_comments(text).splitlines():
        if line.startswith("## "):
            match = HEADING.match(line)
            if match is None:
                current = None
                continue
            current = Release(match.group("version"), match.group("date"))
            releases.append(current)
        elif current is not None:
            current.body.append(line)
    return releases


def render_release(text, version):
    for release in parse_changelog(text):
        if release.version == version:
            body = "\n".join(release.body)
            body = re.sub(r"\n(?:[ \t]*\n)+", "\n\n", body)
            body = re.sub(r"\A(?:[ \t]*\n)+", "", body)
            body = re.sub(r"(?:\n[ \t]*)+\Z", "", body)
            if release.date:
                title = f"{release.version} ({release.date})"
            else:
                title = release.version
            return f"# {title}\n\n{body}\n"
    raise LookupError(version)
